// Service worker for push notifications
// Generated by vite-plugin-pwa, this file handles custom push notification events

self.addEventListener('push', (event) => {
    if (!event.data) {
        return;
    }

    try {
        const data = event.data.json();
        const { title, body, icon, badge, tag, data: notificationData } = data;

        const options = {
            body,
            icon: icon || '/icons/icon-192x192.png',
            badge: badge || '/icons/badge-96x96.png',
            tag: tag || 'gone-notification',
            requireInteraction: false,
            data: notificationData,
        };

        event.waitUntil(
            self.registration.showNotification(title, options)
        );
    } catch (error) {
        console.error('Error parsing push notification:', error);
    }
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();

    const url = event.notification.data?.url || '/';

    event.waitUntil(
        clients.matchAll({ type: 'window', includeUncontrolled: true })
            .then((clientList) => {
                // Check if app is already open
                for (const client of clientList) {
                    if (client.url === url && 'focus' in client) {
                        return client.focus();
                    }
                }
                // Open new window
                if (clients.openWindow) {
                    return clients.openWindow(url);
                }
            })
    );
});
